import heapq

def solve(nums, k):
    # Create a max-heap of size k
    heap = []
    for num in nums:
        # Maintain the heap size to be at most k
        if len(heap) < k:
            heapq.heappush(heap, -num)
        else:
            # If current number is smaller than the largest in the heap, replace it
            if num < -heap[0]:
                heapq.heappop(heap)
                heapq.heappush(heap, -num)
    # The root of the max-heap is the k-th smallest element
    return -heap[0]

