def solve(nums, k):
    # Use a max-heap of size k to keep track of the k smallest elements
    # We use negative numbers to simulate a max-heap in Python's min-heap
    heap = []
    for num in nums:
        if len(heap) < k:
            heapq.heappush(heap, -num)
        else:
